const paint = { meshes: 0, draws: 0, tris: 0, drawnTris: 0 };
app.scene.traverse((o) => { if (!o.isMesh || !(o.name.startsWith('RoadMarkings') || o.name === 'BikeSymbols')) return; paint.meshes++; const t = o.geometry.index ? o.geometry.index.count / 3 : 0; paint.tris += t; if (shown(o) && fr.intersectsObject(o)) { paint.draws++; paint.drawnTris += t; } });
const trees = {}; const tg = app.scene.getObjectByName('Trees');
if (tg) tg.traverse((o) => { if (o.isInstancedMesh && shown(o) && o.count) { const k = o.name.replace(/^Trees_(far_)?/, '').replace(/^[^_]*_[^_]*_/, '').replace(/^ez-[a-z]+-[a-z]+_/, ''); trees[k] = (trees[k] || 0) + o.count; } });
const R = app.renderer.info.render; let drawCalls = 0, triangles = 0;
for (let i = 0; i < 20; i++) { await new Promise((r) => requestAnimationFrame(() => setTimeout(r, 0))); drawCalls = Math.max(drawCalls, R.drawCalls); triangles = Math.max(triangles, R.triangles); }
return { camera: cam.position.toArray().map((v) => +v.toFixed(1)), drawCalls, triangles, paint, trees, road: typeof r !== 'undefined' && r ? r.road.name : null, q: location.search }; } })()

